// Small local helper: place the ball below the field without importing the
// height (coverage intentionally light).
function belowField() {
  return 500;
}

// --- Issue #1: brick bounce -------------------------------------------------
// Each case from ISSUES.md #1 is covered below: per-face bounce, corner,
// push-out, neighbours (seam) and tunnelling.

// Minimal 2D context stub: frame() only needs the calls above.
function mockCtx() {
  const noop = () => {};
  return {
    fillStyle: '',
    font: '',
    fillRect: noop,
    fillText: noop,
    beginPath: noop,
    arc: noop,
    fill: noop,
  };
}

test('brickHit: side face — flips vx only and pushes the ball out', () => {
  const brick = { x: 244, y: 100, w: 72, h: 20, alive: true };
  const ball = { x: 300, y: 110, r: 7, vx: -300, vy: 0 };
  const hits = resolveBrickCollision(ball, [brick], 330, 110);
  assert.equal(hits.length, 1);
  assert.equal(hits[0], brick);
  assert.equal(brick.alive, false);
  assert.equal(ball.vx, 300, 'side hit flips vx');
  assert.equal(ball.vy, 0, 'the other component is left untouched');
  assert.equal(ball.x, brick.x + brick.w + 7, 'ball pushed out to the right');
  assert.ok(!collides(ball, brick), 'ball no longer overlaps the brick');
});

test('brickHit: top/bottom face — flips vy only and pushes the ball out', () => {
  const brick = { x: 100, y: 100, w: 72, h: 20, alive: true };
  const ball = { x: 120, y: 96, r: 7, vx: 40, vy: -300 };
  const hits = resolveBrickCollision(ball, [brick], 120, 150);
  assert.equal(hits.length, 1);
  assert.equal(hits[0], brick);
  assert.equal(brick.alive, false);
  assert.equal(ball.vy, 300, 'top/bottom hit flips vy');
  assert.equal(ball.vx, 40, 'the other component is left untouched');
  assert.equal(ball.y, brick.y + brick.h + 7, 'ball pushed out below the brick');
  assert.ok(!collides(ball, brick));
});

test('brickHit: side face via penetration — smaller overlap axis wins', () => {
  const brick = { x: 100, y: 100, w: 72, h: 20, alive: true };
  // 7 px overlap on x, 14 px on y: the smaller axis (x) is the face hit.
  const ball = { x: 172, y: 110, r: 7, vx: -300, vy: 0 };
  resolveBrickCollision(ball, [brick], 172, 110);
  assert.equal(brick.alive, false);
  assert.equal(ball.vx, 300);
  assert.equal(ball.vy, 0);
  assert.equal(ball.x, brick.x + brick.w + 7);
});

test('brickHit: top/bottom face via penetration — smaller overlap axis wins', () => {
  const brick = { x: 100, y: 100, w: 72, h: 20, alive: true };
  // 7 px overlap on y, 14 px on x: the smaller axis (y) is the face hit.
  const ball = { x: 120, y: 100, r: 7, vx: 0, vy: -300 };
  resolveBrickCollision(ball, [brick], 120, 100);
  assert.equal(brick.alive, false);
  assert.equal(ball.vy, 300);
  assert.equal(ball.vx, 0);
  assert.equal(ball.y, brick.y - 7);
});

test('brickHit: exact corner via penetration — flips both axes', () => {
  const brick = { x: 100, y: 100, w: 40, h: 20, alive: true };
  // Equal 16 px overlap on both axes: diagonal hit, flip both components.
  const ball = { x: 124, y: 108, r: 8, vx: 300, vy: 300 };
  resolveBrickCollision(ball, [brick], 124, 108);
  assert.equal(brick.alive, false);
  assert.equal(ball.vx, -300);
  assert.equal(ball.vy, -300);
  assert.equal(ball.x, brick.x + brick.w + 8);
  assert.equal(ball.y, brick.y - 8);
});

test('brickHit: diagonal corner — flips both axes', () => {
  const brick = { x: 100, y: 100, w: 40, h: 20, alive: true };
  const ball = { x: 160, y: 160, r: 8, vx: 300, vy: 300 };
  const hits = resolveBrickCollision(ball, [brick], 80, 80);
  assert.equal(hits.length, 1);
  assert.equal(brick.alive, false);
  assert.equal(ball.vx, -300);
  assert.equal(ball.vy, -300);
  assert.equal(ball.x, brick.x - 8);
  assert.equal(ball.y, brick.y - 8);
});

test('brickHit: seam — two bricks in one pass, bounce applied exactly once', () => {
  const a = { x: 100, y: 100, w: 72, h: 20, alive: true };
  const b = { x: 180, y: 100, w: 72, h: 20, alive: true };
  const ball = { x: 176, y: 130, r: 7, vx: 0, vy: 300 };
  const hits = resolveBrickCollision(ball, [a, b], 176, 60);
  assert.equal(hits.length, 2);
  assert.equal(a.alive, false);
  assert.equal(b.alive, false);
  assert.equal(ball.vy, -300, 'flipped once: +300 -> -300 (applied twice it would cancel)');
  assert.equal(ball.vx, 0);
  assert.equal(ball.y, a.y - 7, 'ball pushed out above the row');
});

test('brickHit: 2x2 corner — every brick in the way dies, one bounce', () => {
  const a = { x: 100, y: 100, w: 72, h: 20, alive: true };
  const b = { x: 180, y: 100, w: 72, h: 20, alive: true };
  const c = { x: 100, y: 128, w: 72, h: 20, alive: true };
  const d = { x: 180, y: 128, w: 72, h: 20, alive: true };
  const bricks = [a, b, c, d];
  const ball = { x: 176, y: 124, r: 7, vx: 300, vy: 300 };
  const hits = resolveBrickCollision(ball, bricks, 100, 48);
  assert.equal(hits.length, 4);
  assert.ok(bricks.every((br) => !br.alive));
  assert.equal(ball.vx, -300);
  assert.equal(ball.vy, -300);
  assert.equal(ball.y, a.y - 7, 'ball pushed back out above the block');
});

test('brickHit: tunnelling — a fast ball cannot jump over a brick', () => {
  const brick = { x: 100, y: 100, w: 72, h: 20, alive: true };
  // Started BELOW the brick, ended ABOVE it in one step: no overlap at either end.
  const ball = { x: 120, y: 60, r: 7, vx: 0, vy: -300 };
  const hits = resolveBrickCollision(ball, [brick], 120, 150);
  assert.equal(hits.length, 1);
  assert.equal(brick.alive, false);
  assert.equal(ball.vy, 300, 'sweep catches the crossing and flips vy');
  assert.equal(ball.y, brick.y + brick.h + 7, 'ball pushed out below the brick');
  assert.ok(!collides(ball, brick));
});

test('brickHit: no sticky re-flip after the push-out', () => {
  const brick = { x: 244, y: 100, w: 72, h: 20, alive: true };
  const ball = { x: 300, y: 110, r: 7, vx: -300, vy: 0 };
  resolveBrickCollision(ball, [brick], 330, 110);
  assert.ok(!collides(ball, brick), 'ball pushed outside the brick');
  // Next frame the ball flies away from the brick: no second flip, no re-hit.
  ball.x += 10;
  ball.vx = 300;
  const again = resolveBrickCollision(ball, [brick], 323, 110);
  assert.deepEqual(again, []);
  assert.equal(ball.vx, 300);
});

test('frame: ball bounces off a brick and scores', () => {
  const state = createState(1);
  const brick = state.bricks[0];
  state.ball = {
    x: brick.x + brick.w / 2,
    y: brick.y + brick.h + 5,
    r: BALL_R,
    vx: 0,
    vy: -300,
  };
  step(state, 1 / 60); // moves the ball up into the brick, records prevX/prevY
  frame(mockCtx(), state);
  assert.equal(brick.alive, false);
  assert.ok(state.score > 0, 'hitting a brick scores points');
  assert.ok(state.ball.vy > 0, 'ball bounces back down');
});

