export function step(state, dt) {
  const { ball, paddle } = state;

  ball.x += ball.vx * dt;
  ball.y += ball.vy * dt;

edits.newText:
export function step(state, dt) {
  const { ball, paddle } = state;

  // Record where the ball was BEFORE this step: frame() sweeps the brick
  // collision along that segment so fast balls cannot tunnel through bricks.
  ball.prevX = ball.x;
  ball.prevY = ball.y;

  ball.x += ball.vx * dt;
  ball.y += ball.vy * dt;

